const fs=require('node:fs')
const assert=require('node:assert/strict')
const ler=p=>fs.readFileSync(p,'utf8')
const fonte=ler('app/api/visao-geral-projetos/route.ts')
const mutacao=ler('app/api/kanban-obra/cards/route.ts')
const sql=ler('supabase/migrations/20261027130007_kanban_obra_cards_auditados_20261027.sql')
const permissoes=ler('lib/permissoesBlocos.ts')
const helper=ler('lib/kanbanObraPermissoesServer.ts')
const kanban=ler('components/clientes/VendaKanbanObra.tsx')
const venda=ler('components/clientes/VendaObraCentral.tsx')
const geral=ler('app/visao-geral-projetos/page.tsx')
// Cada venda possui seu próprio quadro; sem herança genérica de poderes.
assert.match(fonte,/consultaVendas=consultaVendas\.eq\('id',vendaSelecionada\)/)
assert.match(fonte,/if\(!venda\)continue/)
assert.match(fonte,/i\.destino==='obra'/)
assert.match(helper,/config\?\.acoes\?\.\[acaoId\]/)
assert.match(helper,/config\?\.modulos\?\.\['kanban-obra'\]/)
for(const acao of ['consultar','criar','mover','retirar','restaurar'])assert.match(permissoes,new RegExp('clientes\\.kanban_obra\\.'+acao))
assert.match(mutacao,/permissoesKanbanObra\(u\)/)
assert.match(mutacao,/if\(!acessos\[acao\]\)/)
assert.match(mutacao,/db\.rpc\('alterar_card_kanban_obra_v1'/)
assert.match(sql,/enable row level security/gi)
assert.match(sql,/security invoker/i)
assert.match(sql,/for update/i)
assert.match(sql,/kanban_obra_cards_historico/)
assert.match(sql,/venda_id uuid not null references public\.vendas_obras/)
assert.match(sql,/v_config #>> array\['acoes',v_acao\]/)
assert.match(venda,/<VendaKanbanObra clienteId=\{clienteId\} vendaId=\{vendaId\}/)
assert.match(kanban,/setInterval\(\(\)=>void ler\(\),15_000\)/)
assert.match(geral,/setAcompanhamentos\(j\.acompanhamentos\|\|\[\]\)/)
assert.match(geral,/<CardAcompanhamento key=\{c\.id\} card=\{c\}\/>/)
// Não escrever diretamente em Compras 360, vendas ou dados financeiros.
for(const proibido of [".from('vendas_obras').update", ".from('compras_solicitacoes').update", ".from('ordens_producao').update"])
 assert.ok(!mutacao.includes(proibido)&&!sql.includes(proibido),'Operação proibida: '+proibido)
console.log('Kanban por venda, ACL nominal, auditoria, espelho e isolamento: OK')
